// 雪花算法核心代码
public class SnowflakeIdGenerator {
    private final long workerId;
    private long sequence = 0L;
    private long lastTimestamp = -1L;
    public SnowflakeIdGenerator(long workerId) { this.workerId = workerId; }
    public synchronized long nextId() {
        long timestamp = System.currentTimeMillis();
        if (timestamp < lastTimestamp) throw new RuntimeException("时钟回拨");
        if (timestamp == lastTimestamp) {
            sequence = (sequence + 1) & 4095;
            if (sequence == 0) timestamp = tilNextMillis(lastTimestamp);
        } else sequence = 0L;
        lastTimestamp = timestamp;
        return ((timestamp - 1288834974657L) << 22) | (workerId << 12) | sequence;
    }
    private long tilNextMillis(long last) {
        long t = System.currentTimeMillis();
        while (t <= last) t = System.currentTimeMillis();
        return t;
    }
}

// 短链生成核心代码
public String shorten(String longUrl) {
    String existing = redis.get("url:" + longUrl);
    if (existing != null) return DOMAIN + existing;
    long id = redis.incr("short_url:id");
    String shortCode = base62Encode(id);
    redis.setex("short:" + shortCode, 3600, longUrl);
    redis.setex("url:" + longUrl, 3600, shortCode);
    db.insert(shortCode, longUrl);
    return DOMAIN + shortCode;
}
